-- Written by hand for the held-out set from Spree core models and the column names in its spree_four_three migration.
CREATE TABLE spree_orders (id serial PRIMARY KEY, number varchar(32) NOT NULL, currency varchar(255) NOT NULL, item_total numeric(10,2) NOT NULL, total numeric(10,2) NOT NULL, state varchar(255), completed_at timestamp, created_at timestamp NOT NULL, updated_at timestamp NOT NULL);
CREATE TABLE spree_variants (id serial PRIMARY KEY, sku varchar(255) NOT NULL, cost_price numeric(10,2), cost_currency varchar(255), weight numeric(8,2), product_id int, created_at timestamp NOT NULL, updated_at timestamp NOT NULL);
CREATE TABLE spree_line_items (id serial PRIMARY KEY, variant_id int REFERENCES spree_variants(id), order_id int REFERENCES spree_orders(id), quantity int NOT NULL, price numeric(10,2) NOT NULL, cost_price numeric(10,2), currency varchar(255), adjustment_total numeric(10,2), additional_tax_total numeric(10,2), promo_total numeric(10,2), created_at timestamp NOT NULL, updated_at timestamp NOT NULL);
CREATE TABLE spree_prices (id serial PRIMARY KEY, variant_id int NOT NULL REFERENCES spree_variants(id), amount numeric(10,2), compare_at_amount numeric(10,2), currency varchar(255), min_quantity int NOT NULL, price_list_id int, created_at timestamp, updated_at timestamp);
CREATE TABLE spree_gift_cards (id serial PRIMARY KEY, code varchar(255) NOT NULL, currency varchar(255) NOT NULL, amount numeric(10,2) NOT NULL, amount_used numeric(10,2) NOT NULL, amount_authorized numeric(10,2) NOT NULL, state varchar(255), expires_at date, created_at timestamp NOT NULL, updated_at timestamp NOT NULL);
CREATE TABLE spree_store_credits (id serial PRIMARY KEY, amount numeric(8,2) NOT NULL, amount_used numeric(8,2) NOT NULL, amount_authorized numeric(8,2) NOT NULL, currency varchar(255), memo text, created_at timestamp NOT NULL, updated_at timestamp NOT NULL);
CREATE TABLE spree_payments (id serial PRIMARY KEY, order_id int REFERENCES spree_orders(id), amount numeric(10,2) NOT NULL, state varchar(255), created_at timestamp NOT NULL);
CREATE TABLE spree_refunds (id serial PRIMARY KEY, payment_id int REFERENCES spree_payments(id), amount numeric(10,2) NOT NULL, transaction_id varchar(255), created_at timestamp NOT NULL, updated_at timestamp NOT NULL);
CREATE TABLE spree_tax_rates (id serial PRIMARY KEY, amount numeric(8,5), name varchar(255), created_at timestamp NOT NULL, updated_at timestamp NOT NULL);
